page.css:
:root{--green:#027e6f;--green-d:#014f47;--green-dd:#01332e;--lime:#8fd14f;--cream:#f5f8f5;--sand:#e7f1ee;--card:#fff;--ink:#25302a;--ink2:#586256;--line:rgba(32,64,43,.12);--sbw:270px;--gut:clamp(20px,4vw,60px);--f:'Jost',system-ui,sans-serif;--fs:'Caveat',cursive}
*{box-sizing:border-box}svg{width:18px;height:18px;flex-shrink:0}#nav{display:none}.ph-img{height:auto}
.ph-wrap{position:relative;display:block}.ph-cap{position:absolute;left:8px;right:8px;bottom:8px;z-index:3;background:rgba(1,51,46,.9);color:#fff;font-size:.72rem;line-height:1.32;padding:7px 10px;border-radius:9px;pointer-events:none;box-shadow:0 8px 20px -10px rgba(0,0,0,.55)}.ph-cap b{color:var(--lime);font-weight:700}.ph-cap em{display:block;font-style:normal;color:#b9cbb0;font-size:.66rem;margin-top:2px}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--f);color:var(--ink);background:var(--cream);font-size:16.5px;line-height:1.65;-webkit-font-smoothing:antialiased}
h1,h2,h3{font-family:var(--f);font-weight:700;line-height:1.08;letter-spacing:-.01em;margin:0}
a{color:inherit;text-decoration:none}
.wrap{max-width:1180px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.script{font-family:var(--fs);font-size:1.7rem;color:var(--green);font-weight:700;display:inline-block;line-height:1}
.rv{animation:rvIn .8s both}@keyframes rvIn{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.rv{animation:none}}
.btn{display:inline-flex;align-items:center;gap:9px;font-weight:600;border-radius:999px;padding:14px 26px;font-size:.98rem;border:1.5px solid transparent;cursor:pointer;transition:.16s}
.btn svg{width:18px;height:18px}
.btn-lime{background:var(--lime);color:#1c3510}.btn-lime:hover{background:#b7db56;transform:translateY(-1px)}
.btn-green{background:var(--green-d);color:#fff}.btn-green:hover{background:var(--green)}
.btn-out{border-color:rgba(255,255,255,.5);color:#fff}.btn-out:hover{border-color:#fff;background:rgba(255,255,255,.1)}
/* ===== TOP NAV (horizontal) ===== */
.nav{position:sticky;top:0;z-index:70;background:#fff;border-bottom:1px solid var(--line);box-shadow:0 8px 30px -24px rgba(20,40,25,.6)}
.nav-in{max-width:1300px;margin:0 auto;padding:0 var(--gut);display:flex;align-items:center;gap:18px;min-height:76px}
.logo{display:flex;align-items:center;gap:11px;font-weight:700;font-size:1.12rem;color:var(--green-d);line-height:1.05}
.logo .mk{width:44px;height:44px;flex:0 0 auto;border-radius:13px;background:linear-gradient(150deg,var(--green),var(--lime));display:flex;align-items:center;justify-content:center;color:#16311a}
.logo .mk svg{width:24px;height:24px}
.logo small{display:block;font-family:var(--f);font-weight:600;font-size:.62rem;letter-spacing:.22em;color:var(--green);text-transform:uppercase;margin-top:2px}
.nav-menu{display:flex;align-items:center;gap:2px;margin-left:auto}
.nav-menu>a,.nav-drop-t{padding:9px 13px;border-radius:10px;font-weight:500;font-size:.97rem;color:var(--ink);display:inline-flex;align-items:center;gap:5px;white-space:nowrap;cursor:pointer}
.nav-menu>a:hover,.nav-drop-t:hover{background:var(--sand);color:var(--green-d)}
.nav-menu>a.active,.nav-drop-t.active{color:var(--green-d);background:var(--sand)}
.nav-drop-wrap{position:relative}
.nav-drop-t svg{width:15px;height:15px;color:var(--green)}
.nav-drop{position:absolute;top:calc(100% + 6px);left:0;min-width:255px;background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:0 34px 64px -30px rgba(20,40,25,.5);padding:8px;display:none;flex-direction:column;z-index:80}
.nav-drop a{padding:9px 12px;border-radius:9px;font-size:.9rem;color:var(--ink2);white-space:nowrap}
.nav-drop a:hover{background:var(--sand);color:var(--green-d)}
.nav-drop-wrap:hover .nav-drop,.nav-drop-wrap:focus-within .nav-drop{display:flex}
.nav-tel{display:inline-flex;align-items:center;gap:7px;color:var(--green-d);font-weight:700;font-size:.95rem;margin-left:10px;white-space:nowrap}.nav-tel svg{color:var(--green);width:17px;height:17px}
.nav-quote{margin-left:8px;padding:11px 20px}
.burger{display:none}
/* ===== HERO ===== */
.hero{position:relative;background:var(--cream);overflow:hidden;padding:clamp(40px,5vw,72px) 0}
.hero::before{content:"";position:absolute;top:-140px;right:-120px;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(169,207,70,.22),transparent 70%)}
.hero-in{display:grid;grid-template-columns:1.02fr .98fr;gap:clamp(26px,4vw,56px);align-items:center;position:relative}
.hero h1{font-size:clamp(2.3rem,4.4vw,3.7rem);margin:10px 0 0;color:var(--green-d)}
.hero h1 em{font-style:normal;color:var(--green)}
.hero-sub{margin:20px 0 0;color:var(--ink2);font-size:1.1rem;max-width:40ch}
.hero-cta{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}
.hero-pts{display:flex;flex-wrap:wrap;gap:8px 22px;margin-top:24px;color:var(--green-d);font-weight:600;font-size:.94rem}
.hero-pts span{display:inline-flex;align-items:center;gap:8px}.hero-pts svg{color:var(--green);width:17px;height:17px}
.hero-media{position:relative}
.hero-media .m1{width:100%;aspect-ratio:4/3.9;object-fit:cover;border-radius:220px 220px 28px 28px;box-shadow:0 40px 80px -40px rgba(1,79,71,.4)}
.hero-media .m2{position:absolute;left:-26px;bottom:38px;width:44%;aspect-ratio:1/1;object-fit:cover;border-radius:22px;border:6px solid var(--cream);box-shadow:0 24px 50px -24px rgba(20,40,25,.5)}
.hero-badge{position:absolute;right:6px;top:20px;background:#fff;border-radius:16px;padding:12px 16px;display:flex;align-items:center;gap:11px;box-shadow:0 22px 44px -22px rgba(20,40,25,.4)}
.hero-badge b{font-size:1.4rem;color:var(--green);display:block;line-height:1}.hero-badge small{color:var(--ink2);font-size:.78rem}
.hero-badge .hb{width:42px;height:42px;border-radius:11px;background:rgba(169,207,70,.2);color:var(--green);display:flex;align-items:center;justify-content:center}
/* stats */
.stats{background:var(--green-d);color:#e7efe1}
.stats .wrap{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;padding:30px 0}
.stat b{font-size:2rem;color:var(--lime);display:block;line-height:1}.stat span{font-size:.9rem;color:#c3d3ba}
/* sections */
section.blk{padding:clamp(52px,6vw,90px) 0}
.sec-head{max-width:680px;margin:0 auto 42px;text-align:center}
.sec-head.left{margin-left:0;text-align:left}
.sec-head h2{font-size:clamp(1.9rem,3.3vw,2.7rem);color:var(--green-d);margin-top:6px}
.sec-head p{color:var(--ink2);margin-top:14px;font-size:1.05rem}
/* services */
.sgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.scard{background:var(--card);border-radius:22px;overflow:hidden;box-shadow:0 20px 50px -34px rgba(20,40,25,.35);transition:.18s;display:flex;flex-direction:column}
.scard:hover{transform:translateY(-5px);box-shadow:0 34px 66px -34px rgba(20,40,25,.45)}
.sc-img{position:relative;display:block}.sc-img .ph-img{width:100%;aspect-ratio:16/10;object-fit:cover;display:block}
.sc-ic{position:absolute;left:20px;bottom:-24px;width:52px;height:52px;border-radius:14px;background:var(--lime);color:#1c3510;display:flex;align-items:center;justify-content:center;box-shadow:0 12px 26px -12px rgba(20,40,25,.5)}.sc-ic svg{width:26px;height:26px}
.sc-b{padding:34px 24px 24px}.sc-b h3{font-size:1.22rem;color:var(--green-d)}.sc-b p{color:var(--ink2);font-size:.94rem;margin:8px 0 14px}
.slink{display:inline-flex;align-items:center;gap:6px;color:var(--green);font-weight:600;font-size:.9rem}.slink svg{width:15px;height:15px}
/* about/why */
.why{background:var(--sand)}
.why-grid{display:grid;grid-template-columns:.95fr 1.05fr;gap:clamp(30px,4vw,60px);align-items:center}
.why-media{position:relative}.why-media .ph-img{width:100%;aspect-ratio:4/4.6;object-fit:cover;border-radius:24px 24px 120px 24px}
.why-media .wm-badge{position:absolute;right:-14px;bottom:26px;background:var(--green-d);color:#fff;border-radius:18px;padding:16px 20px;text-align:center;box-shadow:0 24px 50px -24px rgba(0,0,0,.5)}
.why-media .wm-badge b{font-size:1.8rem;color:var(--lime);display:block}.why-media .wm-badge small{font-size:.78rem;color:#c3d3ba}
.why h2{font-size:clamp(1.9rem,3.3vw,2.6rem);color:var(--green-d);margin-top:6px}
.wlist{display:grid;gap:14px;margin:22px 0 26px}
.wlist li{list-style:none;display:flex;gap:12px;align-items:flex-start}
.wlist .wt{width:30px;height:30px;flex:0 0 auto;border-radius:9px;background:rgba(106,156,63,.16);color:var(--green);display:flex;align-items:center;justify-content:center}.wlist .wt svg{width:17px;height:17px}
.wlist b{color:var(--green-d);display:block;font-size:1.02rem}.wlist span{color:var(--ink2);font-size:.94rem}
/* process */
.pgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
.step{background:var(--card);border-radius:20px;padding:28px 22px;position:relative}
.stp-n{font-family:var(--fs);font-size:2.4rem;color:var(--lime);font-weight:700;line-height:1}
.step h3{color:var(--green-d);font-size:1.14rem;margin:6px 0 8px}.step p{color:var(--ink2);font-size:.92rem}
/* gallery */
.gal{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.gal a .ph-img{width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:16px;display:block}
.gal a:first-child{grid-column:span 2;grid-row:span 2}.gal a:first-child .ph-img{height:100%}
/* reviews */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.rev{background:var(--card);border-radius:20px;padding:26px;box-shadow:0 20px 50px -36px rgba(20,40,25,.3)}
.stars{color:#e0a11e;letter-spacing:2px}.rev p{margin:12px 0 16px}.rev b{color:var(--green-d)}.rev small{display:block;color:var(--ink2)}
/* faq */
.faq{max-width:820px;margin:0 auto;display:grid;gap:12px}
.faq details{background:var(--card);border-radius:16px;padding:2px 22px;box-shadow:0 14px 34px -30px rgba(20,40,25,.4)}
.faq summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;gap:14px;align-items:center;padding:18px 0;font-weight:600;font-size:1.06rem;color:var(--green-d)}
.faq summary::-webkit-details-marker{display:none}.faq summary svg{color:var(--green);width:20px;height:20px;transition:.2s}
.faq details[open] summary svg{transform:rotate(180deg)}.faq details p{margin:0 0 18px;color:var(--ink2)}
/* CTA + form */
.cta{background:linear-gradient(155deg,var(--green),var(--green-d));color:#fff;position:relative;overflow:hidden}
.cta::before{content:"";position:absolute;left:-100px;bottom:-120px;width:380px;height:380px;border-radius:50%;background:rgba(169,207,70,.18)}
.cta-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(28px,4vw,56px);align-items:center;position:relative}
.cta h2{color:#fff;font-size:clamp(1.9rem,3.3vw,2.7rem)}.cta p{color:#d6e5cf;margin-top:12px}
.qform{background:#fff;border-radius:22px;padding:28px;box-shadow:0 40px 80px -40px rgba(0,0,0,.5)}
.qform h3{color:var(--green-d);margin-bottom:4px}.qform .sub{color:var(--ink2);font-size:.9rem;margin-bottom:16px}
.frow{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.field{margin-bottom:12px;min-width:0}.field label{display:block;font-size:.82rem;font-weight:600;color:var(--ink);margin-bottom:5px}
.field input,.field select,.field textarea{width:100%;min-width:0;border:1.5px solid var(--line);border-radius:12px;padding:12px 14px;font:inherit;font-size:.95rem;background:#fafbf7;color:var(--ink)}
.field textarea{min-height:92px;resize:vertical}.field :focus{outline:none;border-color:var(--green)}
.qform .btn{width:100%;justify-content:center}.qform .note{text-align:center;color:var(--ink2);font-size:.8rem;margin-top:12px}
/* footer */
footer{background:var(--green-dd);color:#b9cbb0;padding:56px 0 24px}
.foot-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:30px}
footer h4{color:#fff;font-size:.78rem;letter-spacing:.14em;text-transform:uppercase;margin:0 0 14px}
footer a{color:#b9cbb0;display:block;padding:4px 0;font-size:.92rem;overflow-wrap:anywhere}footer a:hover{color:var(--lime)}
.foot-grid>div{min-width:0}.foot-brand p{margin-top:14px;max-width:34ch;font-size:.92rem}
.foot-c a{display:flex;gap:9px;align-items:center}.foot-c svg{color:var(--lime);width:16px;height:16px}
.foot-bot{border-top:1px solid rgba(255,255,255,.12);margin-top:34px;padding-top:18px;display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px;font-size:.85rem;color:#8ea583}
.built{display:inline-flex;align-items:center;gap:8px}.built b{color:var(--lime)}.built-ico{width:22px;height:22px;border-radius:6px}
.mbar{display:none}
/* sticky quote tab + slide-out panel (pure CSS) */
.qbot-tog{position:fixed;opacity:0;pointer-events:none;width:0;height:0}
.qbot-tab{position:fixed;right:0;top:42%;transform:translateY(-50%);z-index:97;display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer;background:linear-gradient(160deg,var(--green),var(--green-d));color:#fff;border-radius:16px 0 0 16px;padding:16px 11px;box-shadow:-10px 0 34px -14px rgba(20,40,25,.6);transition:transform .2s}
.qbot-tab:hover{transform:translateY(-50%) translateX(-3px)}
.qbot-tab svg{width:22px;height:22px;color:var(--lime)}
.qbot-tabtxt{writing-mode:vertical-rl;transform:rotate(180deg);font-weight:700;font-size:.76rem;letter-spacing:.12em;text-transform:uppercase}
.qbot-ov{position:fixed;inset:0;background:rgba(4,12,8,.5);opacity:0;visibility:hidden;z-index:120;transition:opacity .35s,visibility .35s;cursor:pointer}
.qbot-panel{position:fixed;top:0;right:0;height:100%;width:400px;max-width:92vw;z-index:121;background:var(--cream);border-left:1px solid var(--line);box-shadow:-30px 0 70px -24px rgba(0,0,0,.4);transform:translateX(100%);visibility:hidden;transition:transform .4s cubic-bezier(.6,0,.2,1),visibility .4s;display:flex;flex-direction:column;padding:24px 22px 30px;overflow-y:auto}
#qbot:checked ~ .qbot-ov{opacity:1;visibility:visible}
#qbot:checked ~ .qbot-panel{transform:none;visibility:visible}
.qbot-close{align-self:flex-end;width:40px;height:40px;border-radius:11px;background:#fff;border:1px solid var(--line);display:flex;align-items:center;justify-content:center;color:var(--green-d);cursor:pointer;margin-bottom:6px}
.qbot-panel h3{color:var(--green-d);font-size:1.35rem;margin:4px 0 4px}
.qbot-panel .psub{color:var(--ink2);font-size:.92rem;margin:0 0 14px}
.qbot-tel{display:inline-flex;align-items:center;gap:8px;color:var(--green-d);font-weight:700;margin-bottom:16px}.qbot-tel svg{color:var(--green);width:17px;height:17px}
.qbot-panel .qform{padding:0;box-shadow:none;background:transparent}
@media(max-width:768px){.qbot-tab{display:none}}
/* nav collapses to burger + dropdown panel */
@media(max-width:1120px){
 .burger{display:flex;width:46px;height:46px;border-radius:12px;border:1px solid var(--line);background:#fff;align-items:center;justify-content:center;color:var(--green-d);cursor:pointer;margin-left:auto}.burger svg{width:24px;height:24px}
 .nav-menu{position:absolute;top:100%;left:0;right:0;flex-direction:column;align-items:stretch;gap:3px;background:#fff;border-bottom:1px solid var(--line);box-shadow:0 30px 50px -20px rgba(20,40,25,.35);padding:12px var(--gut) 20px;margin-left:0;display:none;max-height:calc(100vh - 76px);overflow:auto}
 #nav:checked ~ .nav-menu{display:flex}
 .nav-menu>a,.nav-drop-t{width:100%;font-size:1.02rem;padding:12px 14px}
 .nav-drop-wrap{display:flex;flex-direction:column}
 .nav-drop{position:static;display:flex;box-shadow:none;border:0;border-radius:0;padding:2px 0 8px 16px;min-width:0}
 .nav-tel{margin-left:0;padding:12px 14px}
 .nav-quote{margin-left:0;margin-top:8px;justify-content:center}
}
/* ===== responsive ===== */
@media(max-width:1024px){
 body{padding-bottom:64px}
 .hero-in,.why-grid,.cta-grid{grid-template-columns:1fr}
 .sgrid,.pgrid,.rev-grid{grid-template-columns:1fr 1fr}
 .stats .wrap{grid-template-columns:1fr 1fr}
 .gal{grid-template-columns:repeat(3,1fr)}
 .foot-grid{grid-template-columns:1fr 1fr}
 .mbar{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:50;background:#fff;border-top:1px solid var(--line);padding:9px 12px;gap:9px}
 .mbar a{flex:1;justify-content:center;padding:12px}
}
@media(max-width:560px){.sgrid,.pgrid,.rev-grid,.gal,.frow,.foot-grid,.stats .wrap{grid-template-columns:1fr}.gal a:first-child{grid-column:auto;grid-row:auto}.hero-media .m2{display:none}}
/* sale bar + band */
.salebar{background:linear-gradient(90deg,var(--green-d),var(--green));color:#fff}
.sale-in{display:flex;align-items:center;justify-content:center;gap:16px;flex-wrap:wrap;padding:11px 0}
.sale-tag{background:var(--lime);color:#123419;font-weight:700;border-radius:999px;padding:4px 13px;font-size:.74rem;letter-spacing:.06em;text-transform:uppercase}
.salebar p{margin:0;font-size:.96rem}.salebar b{color:var(--lime)}
.sale-btn{padding:8px 16px;font-size:.85rem}
.salewrap{padding:clamp(26px,3.5vw,46px) 0;background:var(--cream)}
.salebox{background:linear-gradient(150deg,var(--green-d),var(--green-dd));color:#fff;border-radius:26px;padding:clamp(28px,4vw,52px);display:grid;grid-template-columns:1.5fr .5fr;gap:26px;align-items:center;position:relative;overflow:hidden}
.salebox::before{content:'';position:absolute;right:-70px;top:-70px;width:300px;height:300px;border-radius:50%;background:rgba(143,209,79,.14)}
.sale-copy{position:relative}.sale-copy h2{color:#fff;font-size:clamp(1.7rem,3.2vw,2.6rem);line-height:1.05}
.sale-copy .big{color:var(--lime);font-size:clamp(2.6rem,5vw,4.2rem);display:inline-block}
.sale-copy p{color:#cfe4dc;margin:14px 0 22px;max-width:48ch}
.sale-badge{display:flex;justify-content:center;position:relative}
.sale-badge span{width:150px;height:150px;border-radius:50%;background:var(--lime);color:#123419;display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:800;font-size:2.6rem;line-height:.9;box-shadow:0 22px 50px -18px rgba(143,209,79,.6);transform:rotate(-8deg)}
.sale-badge small{font-size:1rem;letter-spacing:.14em;margin-top:2px}
.hero-sale{display:inline-flex;align-items:center;gap:8px;background:var(--lime);color:#123419;font-weight:700;border-radius:999px;padding:6px 14px;font-size:.82rem;margin-bottom:6px}
@media(max-width:760px){.salebox{grid-template-columns:1fr;text-align:center}.sale-copy p{margin-left:auto;margin-right:auto}}
@media(max-width:560px){.sale-btn{display:none}}
select option{background:#fff;color:var(--ink)}


.subhero{background:linear-gradient(160deg,var(--green-d),var(--green-dd));color:#fff;padding:clamp(38px,5vw,66px) 0 clamp(46px,6vw,74px);position:relative;overflow:hidden}.subhero::before{content:'';position:absolute;right:-90px;top:-90px;width:340px;height:340px;border-radius:50%;background:rgba(143,209,79,.13)}.crumb{display:flex;gap:8px;align-items:center;font-size:.85rem;color:#b9cbb0;margin-bottom:14px;flex-wrap:wrap}.crumb a{color:#cfe4dc}.crumb a:hover{color:var(--lime)}.crumb span{color:#7f9c8a}.subhero h1{font-size:clamp(2rem,3.8vw,3rem);color:#fff;max-width:20ch}.subhero .lead{margin-top:16px;color:#d6e5df;font-size:1.1rem;max-width:60ch}.subhero-in{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:clamp(28px,4vw,54px);align-items:center;position:relative;z-index:2}.subhero-in>*{min-width:0}.subhero-media .hero-media{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:20px;background:#fff;padding:8px;box-shadow:0 40px 80px -38px rgba(0,0,0,.5)}@media(max-width:860px){.subhero-in{grid-template-columns:1fr}.subhero-media{max-width:520px}}.prose{max-width:760px}.prose p{color:var(--ink2);margin:0 0 16px;font-size:1.04rem}.prose h2{color:var(--green-d);font-size:clamp(1.5rem,2.6vw,2rem);margin:30px 0 12px}.subhero h1,.prose h2,.prose h3,.sec-head h2,.side-card h3,.relc b,.scard h3{overflow-wrap:anywhere}.inc{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;margin:8px 0 0;padding:0}.inc li{min-width:0}.inc span{overflow-wrap:anywhere}.inc li{list-style:none;display:flex;gap:11px;align-items:flex-start;background:#fff;border-radius:14px;padding:14px 16px;box-shadow:0 14px 34px -30px rgba(20,40,25,.4)}.inc .t{width:26px;height:26px;flex:0 0 auto;border-radius:8px;background:var(--lime);color:#123419;display:flex;align-items:center;justify-content:center}.inc .t svg{width:16px;height:16px}.split{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:clamp(28px,4vw,52px);align-items:start}.split>*{min-width:0}.side-card{background:var(--green-d);color:#fff;border-radius:20px;padding:26px;position:sticky;top:20px}.side-card h3{color:#fff;font-size:1.2rem}.side-card p{color:#cfe4dc;font-size:.95rem;margin:10px 0 16px}.side-card .btn{width:100%;justify-content:center}.side-card .st{display:flex;align-items:center;gap:9px;color:#fff;font-weight:600;margin-top:14px}.side-card .st svg{color:var(--lime);width:17px}.rel{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.rel>*{min-width:0}.relc b{overflow-wrap:anywhere}.relc{background:#fff;border-radius:16px;padding:20px;display:flex;gap:12px;align-items:center;box-shadow:0 14px 34px -30px rgba(20,40,25,.4)}.relc .ri{width:44px;height:44px;flex:0 0 auto;border-radius:11px;background:rgba(2,126,111,.12);color:var(--green);display:flex;align-items:center;justify-content:center}.relc b{color:var(--green-d);font-size:.98rem}.relc:hover{transform:translateY(-3px)}.relc{transition:.16s}.contact-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(26px,4vw,48px);align-items:start}.contact-grid>*{min-width:0}.cinfo{display:grid;gap:14px}.cinfo .ci{display:flex;gap:13px;align-items:flex-start;background:#fff;border-radius:16px;padding:18px 20px;box-shadow:0 14px 34px -30px rgba(20,40,25,.4)}.cinfo .ci .cic{width:44px;height:44px;flex:0 0 auto;border-radius:12px;background:rgba(2,126,111,.12);color:var(--green);display:flex;align-items:center;justify-content:center}.cinfo b{color:var(--green-d);display:block}.cinfo span{color:var(--ink2);font-size:.94rem}@media(max-width:900px){.inc,.rel,.contact-grid,.split{grid-template-columns:1fr}.side-card{position:static}}
